import csv, json, math
from datetime import date, datetime, timezone
import pyarrow as pa
import pyarrow.parquet as pq

SRC = [('source_a','/data/source_a/users.json'),('source_b','/data/source_b/users.csv'),('source_c','/data/source_c/users.parquet')]
ALIAS = {
 'user_id': ('user_id','id','userId'),
 'name': ('full_name','name','userName'),
 'email': ('email','email_address'),
 'created_date': ('registration_date','created_at','joined'),
 'status': ('status','is_active','active'),
}
OUT = ('name','email','created_date','status')

def miss(v):
    return v is None or (isinstance(v,float) and math.isnan(v))

def pick(r, f):
    for k in ALIAS[f]:
        if k in r and not miss(r[k]):
            return r[k]
    return None

def uid(v):
    if miss(v) or isinstance(v,bool): return None
    try:
        if isinstance(v,int): return v
        s=str(v).strip()
        try: return int(s)
        except: 
            x=float(s)
            return int(x) if math.isfinite(x) and x.is_integer() else None
    except: return None

def txt(v):
    if miss(v): return None
    s=str(v).strip()
    return s or None

def stat(v):
    if miss(v): return None
    if isinstance(v,bool): return 'active' if v else 'inactive'
    s=str(v).strip().lower()
    if s in ('true','1','yes','y','active','enabled'): return 'active'
    if s in ('false','0','no','n','inactive','disabled'): return 'inactive'
    return s or None

def day(v):
    if miss(v): return None
    if isinstance(v,datetime): return v.date().isoformat()
    if isinstance(v,date): return v.isoformat()
    if isinstance(v,(int,float)) and not isinstance(v,bool):
        x=float(v)
        if 1e12 <= x < 1e14: x/=1000
        if 1e8 <= x < 1e11:
            return datetime.fromtimestamp(x,timezone.utc).date().isoformat()
        return None
    s=str(v).strip()
    for fmt in ('%Y-%m-%d','%Y/%m/%d','%m/%d/%Y','%d/%m/%Y','%Y%m%d','%b %d, %Y','%B %d, %Y'):
        try: return datetime.strptime(s,fmt).date().isoformat()
        except: pass
    try: return datetime.fromisoformat(s.replace('Z','+00:00')).date().isoformat()
    except: pass
    if s.isdigit() and len(s) in (10,13): return day(int(s))
    return None

def norm(r):
    u = uid(pick(r,'user_id'))
    if u is None: return None, {}
    d = {}
    for f in OUT:
        raw = pick(r,f)
        if raw is None: continue
        val = day(raw) if f=='created_date' else stat(raw) if f=='status' else txt(raw)
        if val is not None: d[f]=val
    return u, d

def records():
    data=json.load(open('/data/source_a/users.json'))
    if isinstance(data,dict): data=data.get('users',data.get('data',[]))
    for r in data: yield 'source_a', r
    with open('/data/source_b/users.csv',newline='',encoding='utf-8-sig') as f:
        for r in csv.DictReader(f): yield 'source_b', r
    for r in pq.read_table('/data/source_c/users.parquet').to_pylist(): yield 'source_c', r

users={}
for src, rec in records():
    u,d=norm(rec)
    if u is None: continue
    byfield=users.setdefault(u,{})
    for f,v in d.items(): byfield.setdefault(f,{}).setdefault(src,v)

rows=[]; conflicts=[]
for u in sorted(users):
    byfield=users[u]
    row={'user_id':u}
    for f in OUT:
        vals=byfield.get(f,{})
        selected=next((vals[s] for s,_ in SRC if s in vals), None)
        row[f]=selected
        present={s:vals[s] for s,_ in SRC if s in vals}
        if len({json.dumps(v,sort_keys=True) for v in present.values()}) > 1:
            conflicts.append({'user_id':u,'field':f,'values':present,'selected':selected})
    rows.append(row)

schema=pa.schema([('user_id',pa.int64()),('name',pa.string()),('email',pa.string()),('created_date',pa.string()),('status',pa.string())])
table=pa.Table.from_arrays([pa.array([r[f],type=pa.int64()) if f=='user_id' else pa.array([r[f] for r in rows],type=pa.string()) for f in ()],schema=schema) if False else pa.Table.from_arrays([
 pa.array([r['user_id'] for r in rows],type=pa.int64()),
 pa.array([r['name'] for r in rows],type=pa.string()),
 pa.array([r['email'] for r in rows],type=pa.string()),
 pa.array([r['created_date'] for r in rows],type=pa.string()),
 pa.array([r['status'] for r in rows],type=pa.string()),
],schema=schema)
pq.write_table(table,'/app/merged_users.parquet')
json.dump({'total_conflicts':len(conflicts),'conflicts':conflicts},open('/app/conflicts.json','w'),indent=2)
print('users',len(rows),'conflicts',len(conflicts))
